function version(url) {
	var pos = "";
	try {
		pos = getEnc();
	} catch (e) {}

	url += '&ua=' + clientType();
	url += '&formType=' + getformType();
	url += '&saveStatus=' + 1;
	url += '&pos=' + pos;

	var re = /&version=(\d+)/;
	var version = 1;
	if (re.test(url)) {
		var arr = re.exec(url);
		version += parseInt(arr[1]);
		url = url.replace(re, '&version=' + version);
	} else {
		url = url + '&version=1';
	}
	return url;
}
