			} else {
				if(submitOffsetTop > 0){
					$.toast({
						type : 'failure',
						content : data.msg,
						top : submitOffsetTop + "px"
					});
				}else {
					alert(data.msg);
				}
			}
		},
		complete: function(){
			tempSave=false;
			$("#tempsave").text("暂时保存");
		}
	});
