				active = 0;
			}
		}
	} else {
		var editor = UE.getEditor("answer" + questionId);
		var content = editor.getContent();
		if (content.length == 0) {
			active = 0;
		}
	}

	if (active == 1) {
		$("#answerSheet" + questionId).addClass("active");
	} else {
		$("#answerSheet" + questionId).removeClass("active");
	}
