function wrapCode(code) {
	var preElement = $('<pre>').addClass('line-numbers hover newProcedure');
	var codeElement = $('<code>');
	codeElement.addClass('language-plain');
	codeElement.attr('lang', 'Plain Text');
	codeElement.text(code);
	preElement.append(codeElement);
	return preElement.prop('outerHTML');
}

