//连线题处理
function getOneConnLineAnswer(obj) {
	var answerArr = [];
	$(obj).each(function () {
		var name = $(this).parents(".lineOption").attr("index");
		var content = $(this).attr("value");
		var obj = {};
		obj.name = name;
		obj.content = content;
		answerArr.push(obj);
	});

	answerArr.sort(function (a, b) {
		var name1 = a.name || "";
		var name2 = b.name || "";
		return Number(name1) - Number(name2);
	});

	return JSON.stringify(answerArr);
}

