function verifyCode() {
	var courseId = $("#courseId").val() || 0;
	var classId = $("#classId").val() || 0;
	var cpi = $("#cpi").val() || 0;
	var workId = $("#workRelationId").val() || 0;
	var answerId = $("#workAnswerId").val() || 0;
	var inputCode = $("#inputCode").val() || "";
	$.ajax({
		type: "get",
		url: _HOST_CP2_ + "/work/verify/code",
		cache: false,
		dataType: "json",
		async: false,
		data: {
			"courseId": courseId,
			"classId": classId,
			"cpi": cpi,
			"workId": workId,
			"answerId": answerId,
			"inputCode": inputCode
		},
		success: function (data) {
			if (!data.status) {
				workVerifyCode();
				hideWorkVerify();

				$("#inputCode").val("");
				$("#verifyCodeTip").html(data.msg);
				showVerifyTip();
			} else {
				var enc = data.enc;
				$("#workTimesEnc").val(enc);
				hideWorkVerify();
				form1submit();
			}
		}
	});
}
function sortMultiAnswer(answer) {
	if ( !answer || answer.trim().length == 0) {
		return "";
	}
	var answerArray = answer.trim().split('');
	var sortedAnswerArray = answerArray.sort();
	return sortedAnswerArray.join('');
}

